async def main(args: Args) -> Output:
    p = args.params or {}
    q = p.get('q_profile') or []
    prof = q[0] if q and isinstance(q[0], dict) else {}
    goal = str(prof.get('job_goal') or '').strip()
    answer = str(p.get('in_answer_text') or '').strip()
    act = str(p.get('in_action') or '').strip()

    if act in ('复盘', '评分', '打分', 'review'):
        action = '复盘'
    else:
        action = '出题'

    if not prof:
        status = 'not_registered'
        tip = '我还没有你的求职档案。先建档（学校、专业、目标岗位、能力标签），再开始模拟面试。'
    elif not goal:
        status = 'need_more_info'
        tip = '档案里还缺「目标岗位」，模拟面试要有目标岗位才能出对口题。'
    elif action == '复盘' and len(answer) < 20:
        status = 'need_more_info'
        tip = '复盘需要你的作答内容。把刚才的回答（或文字稿）贴给我，我按 STAR 结构逐项打分并给参考说法。'
    else:
        status = 'checked'
        tip = ''

    ret: Output = {
        'v_ok': 'Y' if status == 'checked' else 'N',
        'v_status': status,
        'v_action': action,
        'v_tip': tip,
        'v_goal': goal,
        'v_major': str(prof.get('major') or ''),
        'v_ability': str(prof.get('ability_tags') or ''),
    }
    return ret

import json


async def main(args: Args) -> Output:
    p = args.params or {}
    raw = p.get('llm_questions_json')
    data = []
    if isinstance(raw, list):
        data = raw
    elif isinstance(raw, str) and raw.strip():
        try:
            data = json.loads(raw)
        except Exception:
            data = []
    if not isinstance(data, list):
        data = []
    qs = [q for q in data if isinstance(q, dict)]

    plan = str(p.get('llm_plan') or '')
    lines = ['本次模拟面试共 %d 题，建议按顺序作答：' % len(qs)]
    for i, q in enumerate(qs[:10]):
        lines.append('%d. 【%s】%s' % (i + 1, str(q.get('type') or ''), str(q.get('question') or '')))
        focus = str(q.get('focus') or '')
        if focus:
            lines.append('   观察点：' + focus)
    if plan:
        lines.append('')
        lines.append('作答提示：' + plan)

    ret: Output = {
        'v_reply': '\n'.join(lines),
        'v_questions': qs,
        'v_review': [],
        'v_avg_score': 0,
    }
    return ret

